"""Golden checks for the author's 5.1.2 rig: the files in tests/golden/layout/ were generated by the code BEFORE the speaker-layout work
(commit "golden tests before the layout refactor"). They prove that with the built-in 5.1.2 layout the upmix configs and the router's link sets did
not change by a single byte / link.  Regenerate only on purpose:  python3 tests/test_layout_golden.py --regen   (and say why in the commit).
Run: python3 tests/test_layout_golden.py   (needs PyYAML, numpy, scipy)
"""
import importlib.machinery
import importlib.util
import json
import os
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
GOLD = os.path.join(HERE, "golden", "layout")
REGEN = "--regen" in sys.argv
ok = True
IRDIR = "/GOLDEN-IR"


def check(name, cond):
    global ok
    ok &= bool(cond)
    print(("PASS" if cond else "FAIL"), name)


def load_seteq():
    sp = importlib.util.spec_from_file_location("seteq_gold", os.path.join(HERE, "..", "scripts", "set-eq.py"))
    m = importlib.util.module_from_spec(sp)
    sp.loader.exec_module(m)
    return m


def compare(name, text):
    path = os.path.join(GOLD, name)
    if REGEN:
        os.makedirs(GOLD, exist_ok=True)
        with open(path, "w") as fh:
            fh.write(text)
        print("wrote", path)
        return
    with open(path) as fh:
        check(f"golden {name} is byte-identical", fh.read() == text)


S = load_seteq()
drone2 = list(S.FILTER_SETS["drone2"])
HEIGHTS = {"hp": 140, "lfe_gain": 0.0, "tone": True, "invert": False}
# every upmix kind and flavour, on top of the standing profile, with the same IR directory name
import upmix as _unused  # noqa: E402,F401  (set-eq already put scripts/ on sys.path)
for kind, flavours in (("stereo", ("voice", "balanced", "wide")), ("stereo-ad", ("voice", "balanced", "wide")), ("bed", ("subtle", "balanced", "wide"))):
    for fl in flavours:
        with tempfile.TemporaryDirectory() as td:
            text = S.build_config(drone2, align="all", heights=dict(HEIGHTS), upmix=(kind, fl, td)).replace(td, IRDIR)
        compare(f"upmix-{kind}-{fl}.yml", text)
# the other per-flag shapes of build_config
compare("cfg-bed-align.yml", S.build_config(drone2, align="bed", heights=dict(HEIGHTS)))
compare("cfg-invert.yml", S.build_config(drone2, align="all", invert=["FC", "SL"], heights={"hp": 120, "lfe_gain": -3.0, "tone": False, "delay": 1.5, "invert": True}))
compare("cfg-plain.yml", S.build_config(drone2))

# ---- router: the complete link set after each situation, with the default (author's) layout
os.environ.update(FAKE_PW_STATE=os.path.join(tempfile.mkdtemp(), "s.json"), THEATER_PW_LINK=f"{HERE}/fake-pw-link",
                  THEATER_STATE_DIR=os.path.join(tempfile.mkdtemp(), "state"))
os.environ.pop("THEATER_LAYOUT", None)
os.environ["THEATER_LAYOUT_FILE"] = "/nonexistent/layout.yml"      # no layout file: the built-in 5.1.2 layout, exactly as before
loader = importlib.machinery.SourceFileLoader("tr_gold", os.path.join(HERE, "..", "scripts", "theater-route"))
T = importlib.util.module_from_spec(importlib.util.spec_from_loader("tr_gold", loader))
loader.exec_module(T)
P, U = T.PORTS, T.USB


def save(st):
    json.dump(st, open(os.environ["FAKE_PW_STATE"], "w"))


def load():
    return json.load(open(os.environ["FAKE_PW_STATE"]))


def fresh(chans, cam=True, engine=False, app=None):
    st = {"out": [], "in": [f"{U}:playback_{p}" for p in P], "links": []}
    if cam:
        for n in range(1, 9):
            st["out"].append(f"camilladsp-playback:output_{n}")
            st["in"].append(f"camilladsp-capture:input_{n}")
    for p in chans:
        st["out"].append(f"mpv:output_{p}")
        st["links"].append([f"mpv:output_{p}", f"{U}:playback_{p}"])
    if app:
        for p in ("FL", "FR"):
            st["out"].append(f"{app}:output_{p}")
            st["links"].append([f"{app}:output_{p}", f"{U}:playback_{p}"])
    if engine:
        st["in"] += [f"theater-upmix-in:input_{p}" for p in ("FL", "FR")]
        st["out"] += [f"theater-upmix-out:output_AUX{i}" for i in range(4)]
    save(st)


scen = {}
for label, kw, calls in (
    ("mpv8-on", dict(chans=P), [("on", "film")]),
    ("mpv8-off", dict(chans=P), [("on", "film"), ("off", "film")]),
    ("mpv6-on", dict(chans=["FL", "FR", "FC", "LFE", "SL", "SR"]), [("on", "film")]),
    ("mpv2-on", dict(chans=["FL", "FR"]), [("on", "film")]),
    ("no-cam", dict(chans=P, cam=False), [("on", "film")]),
    ("idle", dict(chans=[]), [("on", "film")]),
    ("chrome-stereo", dict(chans=[], app="Google Chrome"), [("on", "stereo:balanced")]),
    ("engine", dict(chans=[], app="Google Chrome", engine=True), [("on", "stereo-ad:balanced")]),
):
    fresh(**kw)
    res = [T.apply(m, profile=p) for m, p in calls]
    scen[label] = {"results": res, "links": sorted(map(tuple, load()["links"]))}
text = json.dumps(scen, indent=1, sort_keys=True) + "\n"
compare("router-scenarios.json", text)

# the constants other tools import
check("PORTS / USB / ENGINE constants unchanged for the default layout",
      (T.PORTS, T.USB, T.ENGINE_TO_CAM, T.ENGINE_IN, T.ENGINE_OUT) ==
      (["FL", "FR", "RL", "RR", "FC", "LFE", "SL", "SR"], "alsa_output.usb-0d8c_USB_Sound_Device-00.analog-surround-71", [6, 7, 2, 3],
       ["theater-upmix-in:input_FL", "theater-upmix-in:input_FR"], [f"theater-upmix-out:output_AUX{i}" for i in range(4)]))
if REGEN:
    sys.exit(0)
print("ALL PASS" if ok else "SOME FAILED")
sys.exit(0 if ok else 1)
